const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_16x9';
pres.author = 'WorkspaceX';
pres.title = '团队协作：让 1+1 > 2';

const FONT = '微软雅黑';
const COLOR_PRIMARY = '1F4E79';
const COLOR_ACCENT = '2E75B6';
const COLOR_LIGHT = 'D6E4F0';
const COLOR_WHITE = 'FFFFFF';
const COLOR_DARK = '333333';

// Helper: add consistent footer
function addFooter(slide, pageNum) {
  slide.addText(`${pageNum} / 5`, {
    x: 8.8, y: 5.2, w: 1, h: 0.3,
    fontSize: 9, color: '999999', fontFace: FONT, align: 'right'
  });
}

// ===== Slide 1: Title =====
const s1 = pres.addSlide();
s1.background = { fill: COLOR_PRIMARY };
s1.addText('团队协作', {
  x: 0.8, y: 1.2, w: 8.4, h: 1.2,
  fontSize: 44, bold: true, color: COLOR_WHITE, fontFace: FONT, align: 'center'
});
s1.addText('让 1 + 1 > 2', {
  x: 0.8, y: 2.4, w: 8.4, h: 0.8,
  fontSize: 28, color: COLOR_LIGHT, fontFace: FONT, align: 'center'
});
s1.addShape(pres.ShapeType.rect, {
  x: 3.5, y: 3.4, w: 3, h: 0.04, fill: { color: COLOR_LIGHT }
});
s1.addText('高效协同 · 信任驱动 · 结果导向', {
  x: 0.8, y: 3.7, w: 8.4, h: 0.6,
  fontSize: 16, color: COLOR_LIGHT, fontFace: FONT, align: 'center'
});

// ===== Slide 2: Why Team Collaboration Matters =====
const s2 = pres.addSlide();
s2.addText('为什么需要团队协作？', {
  x: 0.5, y: 0.3, w: 9, h: 0.7,
  fontSize: 28, bold: true, color: COLOR_PRIMARY, fontFace: FONT
});
s2.addShape(pres.ShapeType.rect, {
  x: 0.5, y: 1.0, w: 2, h: 0.04, fill: { color: COLOR_ACCENT }
});

const reasons = [
  { title: '复杂问题需要多元视角', desc: '单一角色难以覆盖所有盲区，跨职能协作能更快定位根因。' },
  { title: '加速交付与迭代', desc: '并行分工缩短周期，及时同步减少返工，让产品更快触达用户。' },
  { title: '激发创新与归属感', desc: '心理安全的团队更愿意分享想法，碰撞出超越个人的解决方案。' }
];

reasons.forEach((r, i) => {
  const yPos = 1.4 + i * 1.2;
  s2.addShape(pres.ShapeType.roundRect, {
    x: 0.5, y: yPos, w: 9, h: 1.0,
    fill: { color: i % 2 === 0 ? COLOR_LIGHT : COLOR_WHITE },
    rectRadius: 0.1, line: { color: COLOR_ACCENT, width: 0.5 }
  });
  s2.addText(r.title, {
    x: 0.8, y: yPos + 0.1, w: 8.4, h: 0.4,
    fontSize: 16, bold: true, color: COLOR_PRIMARY, fontFace: FONT
  });
  s2.addText(r.desc, {
    x: 0.8, y: yPos + 0.5, w: 8.4, h: 0.4,
    fontSize: 13, color: COLOR_DARK, fontFace: FONT
  });
});
addFooter(s2, 2);

// ===== Slide 3: Core Principles =====
const s3 = pres.addSlide();
s3.addText('高效协作的四大支柱', {
  x: 0.5, y: 0.3, w: 9, h: 0.7,
  fontSize: 28, bold: true, color: COLOR_PRIMARY, fontFace: FONT
});
s3.addShape(pres.ShapeType.rect, {
  x: 0.5, y: 1.0, w: 2, h: 0.04, fill: { color: COLOR_ACCENT }
});

const pillars = [
  { icon: '🎯', title: '共同目标', desc: '对齐 OKR / 里程碑，确保每个人知道"为什么做"和"做到什么程度"。' },
  { icon: '💬', title: '透明沟通', desc: '信息默认公开，决策有据可查；异步优先，同步用于对齐和决断。' },
  { icon: '🤝', title: '信任与授权', desc: '明确 RACI，给执行者决策空间；复盘对事不对人，建立心理安全。' },
  { icon: '🔄', title: '持续反馈', desc: '短周期 Review + 回顾会，把改进嵌入流程而非依赖个人自觉。' }
];

pillars.forEach((p, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const xPos = 0.5 + col * 4.7;
  const yPos = 1.3 + row * 1.9;

  s3.addShape(pres.ShapeType.roundRect, {
    x: xPos, y: yPos, w: 4.4, h: 1.7,
    fill: { color: COLOR_WHITE },
    shadow: { type: 'outer', blur: 4, offset: 2, color: 'CCCCCC', opacity: 0.4 },
    rectRadius: 0.12
  });
  s3.addText(p.icon, {
    x: xPos + 0.2, y: yPos + 0.15, w: 0.6, h: 0.6,
    fontSize: 28, align: 'center', valign: 'middle'
  });
  s3.addText(p.title, {
    x: xPos + 0.9, y: yPos + 0.15, w: 3.2, h: 0.45,
    fontSize: 16, bold: true, color: COLOR_PRIMARY, fontFace: FONT, valign: 'middle'
  });
  s3.addText(p.desc, {
    x: xPos + 0.3, y: yPos + 0.7, w: 3.8, h: 0.85,
    fontSize: 12, color: COLOR_DARK, fontFace: FONT, valign: 'top'
  });
});
addFooter(s3, 3);

// ===== Slide 4: Practical Methods & Tools =====
const s4 = pres.addSlide();
s4.addText('落地方法与工具', {
  x: 0.5, y: 0.3, w: 9, h: 0.7,
  fontSize: 28, bold: true, color: COLOR_PRIMARY, fontFace: FONT
});
s4.addShape(pres.ShapeType.rect, {
  x: 0.5, y: 1.0, w: 2, h: 0.04, fill: { color: COLOR_ACCENT }
});...[6372 chars total]
